#include "PlanRules.h"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <locale>
int wmain(int argc,wchar_t** argv){try{if(argc!=3&&argc!=4&&argc!=5&&argc!=6)throw std::runtime_error("usage: PlanAnalyse cache.tsv NEW_output_directory");const std::filesystem::path cache=argv[1],output=argv[2];if(std::filesystem::exists(output)||!std::filesystem::create_directory(output))throw std::runtime_error("output directory must be new");std::ifstream input(cache);input.imbue(std::locale::classic());if(!input)throw std::runtime_error("cache input unavailable");auto plan=bcp::readCache(input);if(argc>=4){std::ifstream supplement{std::filesystem::path(argv[3])};if(!supplement)throw std::runtime_error("endpoint supplement unavailable");bcp::readEndpointSupplement(supplement,plan);}if(argc>=5){std::ifstream decisions{std::filesystem::path(argv[4])};if(!decisions)throw std::runtime_error("axis decisions unavailable");bcp::readAxisExclusions(decisions,plan);}if(argc==6){std::ifstream prefixes{std::filesystem::path(argv[5])};if(!prefixes)throw std::runtime_error("opening prefixes unavailable");bcp::readOpeningPrefixes(prefixes,plan);}const auto result=bcp::analyse(plan);std::ofstream file(output/L"analysis.json",std::ios::binary);file.exceptions(std::ios::failbit|std::ios::badbit);file<<bcp::toJson(plan,result);file.close();std::cout<<"walls="<<plan.walls.size()<<" openings="<<plan.openings.size()<<" axisCandidates="<<result.axes.size()<<" issues="<<result.issues.size()<<'\n';return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
